import React, { Component } from 'react';
import ControllerDisplay from './ControllerDisplay';
import './FrameList.css';

export default class FrameList extends Component {
  render() {
    return <div className='frame-list'>
      {this.props.frames.map(({state, controller}, i) => {
        return <ControllerDisplay
          controller={controller}
          onClick={() => this.props.onPick(i - 1)}
          selected={this.props.currentFrame === i - 1}
        />
      })}
    </div>;
  }
}
